<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Dashboard</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="app"><aside class="sidebar"><?php include "../partials/sidebar.php";?></aside><main class="main"><header class="topbar"><div class="module-tag">Workspace / <b>Admin</b></div><div class="top-user"><div class="avatar"><?=strtoupper(substr(user()['name'],0,2))?></div><?=htmlspecialchars(user()['name'])?></div></header><section class="content"><div class="page-head"><div><p class="eyebrow">ADMIN MODULE</p><h1>Admin Dashboard</h1><p>Welcome back. Your workspace is limited to services assigned to your role.</p></div></div><div class="stats"><?php foreach($stats as $s):?><div class="stat"><span><?=$s[0]?></span><strong><?=is_numeric($s[1])&&strpos($s[0],'Collected')!==false?money($s[1]):htmlspecialchars($s[1])?></strong></div><?php endforeach;?></div><div class="grid"><section class="card"><h2>Services & Responsibilities</h2><p>Available to this module</p><?php foreach($services as $s):?><div class="service"><div class="service-icon">◆</div><div><b><?=$s[0]?></b><small><?=$s[1]?></small></div></div><?php endforeach;?></section><section class="card"><h2>Role Access</h2><p>Signed in as <b><?=htmlspecialchars(str_replace('_',' ',ucfirst(user()['role'])))?></b></p><div class="service"><div><b>Module</b><small><?=htmlspecialchars(ucfirst(user()['module']))?></small></div></div><div class="service"><div><b>Access control</b><small>Server-side module checks prevent users from opening another module's workspace.</small></div></div></section></div></section></main></div></body></html>